"""
[fogSpike2]

The fog probe, second round (TrigScript 4, S4). Hand-written eudplib, made by probes/lib/fog-gen-2.mts. Each brush
size is a flyer of its own, made on a tile and taken away in the same trigger pass; every type's sight range is
written to its size at the top of every pass and never changed within it. The vision countdown (1.16.1 0x51CE98) is
written to 1 after each pass.

  A   2  one brush (size 5) jumping between two places: the old place goes dark at once (as round 1)?
  C   6  the sizes, 1 to 6 (top row) and 7 to 11 (lower row): each a different size now?
  E  12  four pictures, 4 s each: dancer, apple, "Bad Apple", dancer white on black
  F  28  the animation, 72 frames looped
  H  34  top row: ground Map Revealers at sight 0 (a 3x3?); lower row: size-1 air brushes (3 wide, 4 tall)
  I  38  the dancer painted 3, 4, 5, 6, 7, 8, 10 times a frame (7 x 3 s): when does "Cannot create more units." start?
"""
from eudplib import *

LOC = "Pixel"
COUNTDOWN = 0x51CE98
REVEALER_FLAGS = 0x664080 + 101 * 4   # units.dat flags of the Map Revealer; 0x4 = flyer
DATA = Db(bytes.fromhex(""))
PICS = {"dancer":0,"apple":138,"text":223,"inverted":367}
ANIM = 456

f = EUDVariable()
anim = EUDVariable()
toggle = EUDVariable()
tick = EUDVariable()


def u(s):
    return s.encode("utf-8")


def show(s):
    DoActions(DisplayText(u(s)))


@EUDFunc
def brush(x, y, r):
    left = x * 32
    top = y * 32
    f_setloc(LOC, left, top, left + 32, top + 32)
    EUDSwitch(r)
    if EUDSwitchCase()(1):
        DoActions([CreateUnit(1, "Zerg Scourge", LOC, P1), RemoveUnit("Zerg Scourge", P1)])
        EUDBreak()
    if EUDSwitchCase()(2):
        DoActions([CreateUnit(1, "Zerg Mutalisk", LOC, P1), RemoveUnit("Zerg Mutalisk", P1)])
        EUDBreak()
    if EUDSwitchCase()(3):
        DoActions([CreateUnit(1, "Terran Wraith", LOC, P1), RemoveUnit("Terran Wraith", P1)])
        EUDBreak()
    if EUDSwitchCase()(4):
        DoActions([CreateUnit(1, "Terran Valkyrie", LOC, P1), RemoveUnit("Terran Valkyrie", P1)])
        EUDBreak()
    if EUDSwitchCase()(5):
        DoActions([CreateUnit(1, "Protoss Corsair", LOC, P1), RemoveUnit("Protoss Corsair", P1)])
        EUDBreak()
    if EUDSwitchCase()(6):
        DoActions([CreateUnit(1, "Terran Dropship", LOC, P1), RemoveUnit("Terran Dropship", P1)])
        EUDBreak()
    if EUDSwitchCase()(7):
        DoActions([CreateUnit(1, "Protoss Shuttle", LOC, P1), RemoveUnit("Protoss Shuttle", P1)])
        EUDBreak()
    if EUDSwitchCase()(8):
        DoActions([CreateUnit(1, "Zerg Guardian", LOC, P1), RemoveUnit("Zerg Guardian", P1)])
        EUDBreak()
    if EUDSwitchCase()(9):
        DoActions([CreateUnit(1, "Zerg Devourer", LOC, P1), RemoveUnit("Zerg Devourer", P1)])
        EUDBreak()
    if EUDSwitchCase()(10):
        DoActions([CreateUnit(1, "Terran Science Vessel", LOC, P1), RemoveUnit("Terran Science Vessel", P1)])
        EUDBreak()
    if EUDSwitchCase()(11):
        DoActions([CreateUnit(1, "Terran Battlecruiser", LOC, P1), RemoveUnit("Terran Battlecruiser", P1)])
        EUDBreak()
    EUDEndSwitch()


@EUDFunc
def paint(start):
    p = EUDVariable()
    p << start
    if EUDInfLoop()():
        v = f_dwread_epd(p)
        EUDBreakIf(v == 0xFFFFFFFF)
        p += 1
        w0, w1, bx, by, br, b3 = f_dwbreak(v)
        brush(bx, by, br)
    EUDEndInfLoop()
    EUDReturn(p + 1)


def center(tx, ty):
    f_setloc(LOC, tx * 32, ty * 32, tx * 32 + 32, ty * 32 + 32)
    DoActions(CenterView(LOC))


def during(a, b):
    return EUDIf()([f >= a, f < b])


def at(n):
    return EUDIf()(f == n)


def afterTriggerExec():
    f.__iadd__(1)
    # Every brush type's sight, the same every frame.
    DoActions([
        SetMemoryX(0x663238 + 44, SetTo, 16777216, -16777216),
        SetMemoryX(0x663238 + 40, SetTo, 33554432, -16777216),
        SetMemoryX(0x663238 + 8, SetTo, 3, 255),
        SetMemoryX(0x663238 + 56, SetTo, 262144, 16711680),
        SetMemoryX(0x663238 + 60, SetTo, 5, 255),
        SetMemoryX(0x663238 + 8, SetTo, 100663296, -16777216),
        SetMemoryX(0x663238 + 68, SetTo, 1792, 65280),
        SetMemoryX(0x663238 + 44, SetTo, 8, 255),
        SetMemoryX(0x663238 + 60, SetTo, 589824, 16711680),
        SetMemoryX(0x663238 + 8, SetTo, 2560, 65280),
        SetMemoryX(0x663238 + 12, SetTo, 11, 255),
        SetMemoryX(0x663238 + 100, SetTo, 0, 0xFF00),   # the Map Revealer's sight: 0, for step H
    ])
    if at(1):
        DoActions([RemoveUnit("(any unit)", P1), RemoveUnit("(any unit)", P2)])
        center(64, 48)
        show("\x04S4 fog probe, round 2. Each brush size is a unit type of its own now.")
    EUDEndIf()
    if at(48):
        show("\u0011A: one brush jumping every half second. Does the old place go dark at once (as in round 1)?")
    EUDEndIf()
    if at(144):
        show("\u0011C: sizes 1-6 top row, 7-11 lower row (minimap). Each a DIFFERENT size now?")
    EUDEndIf()
    if at(288):
        show("\u0011E: pictures, 4 s each: dancer, apple, 'Bad Apple', dancer white on black. Screenshot the minimap, please.")
    EUDEndIf()
    if at(672):
        show("\u0011F: the animation, 72 frames looped.")
    EUDEndIf()
    if at(816):
        show("\u0011H: top row ground revealers at sight 0 (3x3 squares?), lower row air size 1 (3 wide, 4 tall).")
    EUDEndIf()
    if at(912):
        show("\u0011I: the dancer painted 3x, 4x, 5x, 6x, 7x, 8x, 10x a frame, 3 s each. When does 'Cannot create more units.' start?")
    EUDEndIf()
    if during(48, 144):
        tick.__iadd__(1)
        if EUDIf()(tick >= 12):
            tick << 0
            toggle << 1 - toggle
        EUDEndIf()
        if EUDIf()(toggle == 0):
            brush(56, 48, 5)
        if EUDElse()():
            brush(72, 48, 5)
        EUDEndIf()
    EUDEndIf()
    if during(144, 288):
        brush(5, 22, 1)
        brush(13, 22, 2)
        brush(23, 22, 3)
        brush(35, 22, 4)
        brush(49, 22, 5)
        brush(65, 22, 6)
        brush(11, 64, 7)
        brush(31, 64, 8)
        brush(53, 64, 9)
        brush(77, 64, 10)
        brush(103, 64, 11)
    EUDEndIf()
    if during(288, 384):
        paint(EPD(DATA) + 0)
    EUDEndIf()
    if during(384, 480):
        paint(EPD(DATA) + 138)
    EUDEndIf()
    if during(480, 576):
        paint(EPD(DATA) + 223)
    EUDEndIf()
    if during(576, 672):
        paint(EPD(DATA) + 367)
    EUDEndIf()
    if at(672):
        anim << EPD(DATA) + ANIM
    EUDEndIf()
    if during(672, 816):
        anim << paint(anim)
        if EUDIf()(f_dwread_epd(anim) == 0xFFFFFFFE):
            anim << EPD(DATA) + ANIM
        EUDEndIf()
    EUDEndIf()
    if during(816, 912):
        DoActions(SetMemoryX(REVEALER_FLAGS, SetTo, 0, 4))
        f_setloc(LOC, 1536, 1280, 1568, 1312)
        DoActions([CreateUnit(1, "Map Revealer", LOC, P1), RemoveUnit("Map Revealer", P1)])
        f_setloc(LOC, 2048, 1280, 2080, 1312)
        DoActions([CreateUnit(1, "Map Revealer", LOC, P1), RemoveUnit("Map Revealer", P1)])
        f_setloc(LOC, 2560, 1280, 2592, 1312)
        DoActions([CreateUnit(1, "Map Revealer", LOC, P1), RemoveUnit("Map Revealer", P1)])
        DoActions(SetMemoryX(REVEALER_FLAGS, SetTo, 4, 4))
        brush(48, 56, 1)
        brush(64, 56, 1)
        brush(80, 56, 1)
    EUDEndIf()
    if during(912, 984):
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
    EUDEndIf()
    if at(912):
        show("\u0011I: 3x a frame (411 units made and removed a frame)")
    EUDEndIf()
    if during(984, 1056):
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
    EUDEndIf()
    if at(984):
        show("\u0011I: 4x a frame (548 units made and removed a frame)")
    EUDEndIf()
    if during(1056, 1128):
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
    EUDEndIf()
    if at(1056):
        show("\u0011I: 5x a frame (685 units made and removed a frame)")
    EUDEndIf()
    if during(1128, 1200):
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
    EUDEndIf()
    if at(1128):
        show("\u0011I: 6x a frame (822 units made and removed a frame)")
    EUDEndIf()
    if during(1200, 1272):
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
    EUDEndIf()
    if at(1200):
        show("\u0011I: 7x a frame (959 units made and removed a frame)")
    EUDEndIf()
    if during(1272, 1344):
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
    EUDEndIf()
    if at(1272):
        show("\u0011I: 8x a frame (1096 units made and removed a frame)")
    EUDEndIf()
    if during(1344, 1416):
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
    EUDEndIf()
    if at(1344):
        show("\u0011I: 10x a frame (1370 units made and removed a frame)")
    EUDEndIf()
    if at(1416):
        show("\x04Done.")
    EUDEndIf()
    DoActions(SetMemory(COUNTDOWN, SetTo, 1))
